// src/pages/SearchPage.js

import React, { useState } from "react";
import { searchMovies, getMovieDetail } from "../api/movieApi";
import { getPosterFromTMDB } from "../api/tmdbApi";
import MovieCard from "../components/MovieCard"; // 재사용할 MovieCard 컴포넌트
import '../styles.css'; // MovieCard 스타일이 포함된 CSS 파일

const SearchPage = () => {
  const [query, setQuery] = useState("");
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [hasSearched, setHasSearched] = useState(false); // 검색 여부 상태 추가

  const handleSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setErrorMsg("");
    setMovies([]);
    setHasSearched(true); // 검색 버튼을 눌렀음을 기록

    try {
      const results = await searchMovies(query);

      // ✅ 불필요한 영화 필터링
    const filteredResults = results
    .filter(movie => movie.openDt) // 개봉일 없는 영화 제외
    .filter(movie => movie.movieNm.includes(query)) // 제목 유사도 기준 필터
    .slice(0, 10); // 최대 10개

      
      if (results.length === 0) {
        setErrorMsg(`'${query}'에 대한 검색 결과가 없습니다.`);
        setLoading(false);
        return;
      }
      
      const enrichedMovies = await Promise.all(results.map(async (movie, index) => {
        const detail = await getMovieDetail(movie.movieCd);
        const year = detail.openDt?.substring(0, 4) || "";
        const posterUrl = await getPosterFromTMDB(movie.movieNm, year, {
          movieNmEn: detail.movieNmEn,
          nation: detail.nations?.[0]?.nationNm,
        });

        // ⭐️ 1. MovieCard에 필요한 정확한 데이터 구조로 가공합니다.
        return {
          id: movie.movieCd,
          // 검색 결과는 순위가 없으므로 rank는 표시하지 않음 (null 또는 생략)
          // MovieCard 컴포넌트는 rank가 없을 경우 배지를 렌더링하지 않도록 수정하는 것이 좋습니다.
          rank: null, 
          title: movie.movieNm,
          englishTitle: detail.movieNmEn || "N/A",
          posterPath: posterUrl || "https://via.placeholder.com/400x600?text=No+Image",
          // 검색 결과에는 예매율/누적관객 정보가 없으므로 대체 텍스트 제공
          summary: {
            salesShare: 'N/A', // KOFIC 검색 API는 예매율 정보를 제공하지 않습니다.
            audiAcc: 'N/A',   // KOFIC 검색 API는 누적관객 정보를 제공하지 않습니다.
          },
          details: {
            "개봉일": detail.openDt ? detail.openDt.replace(/(\d{4})(\d{2})(\d{2})/, '$1.$2.$3') : "N/A",
            "감독": detail.directors?.[0]?.peopleNm || "N/A",
            "출연": detail.actors?.slice(0, 3).map(a => a.peopleNm).join(', ') + (detail.actors?.length > 3 ? '...' : ''),
            "장르": detail.genres?.map(g => g.genreNm).join(', ') || "N/A",
            "상영 시간": `${detail.showTm || "N/A"}분`,
          },
        };
      }));
      
      setMovies(enrichedMovies);

    } catch (error) {
      setErrorMsg("영화 검색 중 오류가 발생했습니다.");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    // ⭐️ 2. 전체적인 UI 구조를 BoxOffice와 유사하게 변경
    <div className="search-page-container">
      <h1 className="page-title">영화 검색</h1>

      <div className="search-bar">
        <input
          type="text"
          placeholder="영화 제목을 입력하세요"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          className="search-input"
        />
        <button onClick={handleSearch} className="search-button">
          검색
        </button>
      </div>

      {loading && <div className="page-message">🔍 검색 중...</div>}
      {errorMsg && <div className="page-message">{errorMsg}</div>}
      
      {/* ⭐️ 3. 검색 결과를 CSS Grid와 MovieCard로 렌더링 */}
      { !loading && movies.length > 0 && (
        <div className="search-results-grid">
          {movies.map((movie) => (
            <MovieCard key={movie.id} movie={movie} />
          ))}
        </div>
      )}

      { !loading && movies.length === 0 && hasSearched && !errorMsg && (
        <div className="page-message">검색 결과가 없습니다.</div>
      )}
    </div>
  );
};

export default SearchPage;
